# Re-arm the runner's INT/TERM handlers after a nested orchestrator (cycle,
# parallel) calls `trap - INT TERM` to clear its own handler layer.
_runner_rearm_traps() {
    trap '_runner_signal_trap INT' INT
    trap '_runner_signal_trap TERM' TERM
}

